import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.CPvOxTBX.js";const p=JSON.parse('{"title":"Translation sources","description":"","frontmatter":{},"headers":[],"relativePath":"guide/translation-sources.md","filePath":"guide/translation-sources.md","lastUpdated":1792511382000}'),n={name:"guide/translation-sources.md"};function s(i,e,d,l,c,u){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="translation-sources" tabindex="-1">Translation sources <a class="header-anchor" href="#translation-sources" aria-label="Permalink to &quot;Translation sources&quot;">​</a></h1><p>Ciyue&#39;s translation page can query many translation sources at once. Every enabled source is asked in parallel, and each answer appears as its own card — so you can compare how Google, DeepL, and an LLM each translate the same sentence, side by side.</p><h2 id="managing-sources" tabindex="-1">Managing sources <a class="header-anchor" href="#managing-sources" aria-label="Permalink to &quot;Managing sources&quot;">​</a></h2><p>Open the translation page, tap the settings icon, and you will find the <strong>Translation Sources</strong> list:</p><ul><li><strong>Toggle</strong> each source on or off. At least one source must stay enabled.</li><li><strong>Drag</strong> a source by its handle to reorder it; result cards follow the same order.</li><li>Sources that need configuration show <strong>Configured</strong> / <strong>Not configured</strong>. Tap into the expanded area to fill in the required fields.</li><li>Enabled sources that are not configured are skipped during translation, with a hint shown under the results.</li></ul><p>By default only the provider you used before is enabled, so upgrading does not change your existing behavior.</p><h2 id="free-sources-no-api-key" tabindex="-1">Free sources (no API key) <a class="header-anchor" href="#free-sources-no-api-key" aria-label="Permalink to &quot;Free sources (no API key)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Notes</th></tr></thead><tbody><tr><td>Google</td><td>Public web endpoint of Google Translate</td></tr><tr><td>Microsoft</td><td>Microsoft Edge translate endpoint</td></tr><tr><td>DeepL (Free)</td><td>DeepL web endpoint; may return alternative translations</td></tr><tr><td>Baidu</td><td>Baidu Translate web endpoint</td></tr><tr><td>Tencent</td><td>Tencent TransMart web endpoint</td></tr><tr><td>Volcengine</td><td>Volcengine web endpoint</td></tr><tr><td>Yandex (Free)</td><td>Yandex Translate free endpoint</td></tr></tbody></table><h2 id="official-api-sources-your-own-api-key" tabindex="-1">Official API sources (your own API key) <a class="header-anchor" href="#official-api-sources-your-own-api-key" aria-label="Permalink to &quot;Official API sources (your own API key)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>What you need</th><th>Where to get it</th></tr></thead><tbody><tr><td>DeepL</td><td>API key (free keys end with <code>:fx</code> and automatically use the free endpoint)</td><td><a href="https://www.deepl.com/pro-api" target="_blank" rel="noreferrer">DeepL API</a></td></tr><tr><td>Google Cloud</td><td>Cloud Translation API key</td><td><a href="https://console.cloud.google.com/apis/api/translate.googleapis.com" target="_blank" rel="noreferrer">Google Cloud Console</a></td></tr><tr><td>Azure</td><td>Translator key <strong>and</strong> the resource&#39;s region</td><td><a href="https://portal.azure.com/#create/Microsoft.CognitiveServicesTextTranslation" target="_blank" rel="noreferrer">Azure Portal</a></td></tr><tr><td>Yandex Cloud</td><td>API key <strong>and</strong> folder ID</td><td><a href="https://console.cloud.yandex.com/" target="_blank" rel="noreferrer">Yandex Cloud Console</a></td></tr><tr><td>DeepLX</td><td>URL of your own DeepLX instance</td><td><a href="https://github.com/OwO-Network/DeepLX" target="_blank" rel="noreferrer">DeepLX</a></td></tr></tbody></table><h2 id="ai-providers-as-translation-sources" tabindex="-1">AI providers as translation sources <a class="header-anchor" href="#ai-providers-as-translation-sources" aria-label="Permalink to &quot;AI providers as translation sources&quot;">​</a></h2><p>Every AI provider configured in <strong>Settings → AI</strong> (OpenAI, Gemini, DeepSeek, Anthropic, OpenRouter, SiliconFlow, Zhipu, xAI, Ollama, and others) is also a translation source. A provider counts as configured when it has a model and an API key in AI Settings (local providers such as Ollama do not need a key). You can enable several AI providers alongside the machine-translation sources and compare their output.</p><h2 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Please read</p><p>The sources labelled <strong>free</strong> call the public web or client endpoints of the respective services. They are <strong>not</strong> official open APIs. A provider may change, restrict, or shut down such an endpoint at any time, and using it may not comply with the provider&#39;s terms of service. These sources are provided as options only; whether to enable them is your decision, and you use them at your own risk.</p><p>Sources that require an API key use credentials you obtain yourself. Any fees, quotas, and compliance obligations are between you and the provider.</p><p>The text you translate is sent directly to the servers of <strong>every source you enable</strong>. Do not translate content you are not comfortable sharing with those third parties. Ciyue itself does not collect or upload your translation content.</p></div><p>If a free source suddenly stops working, it most likely means the provider changed or blocked the endpoint — not a bug in Ciyue. Disable that source and rely on the others, or switch to an official API source.</p>',15)]))}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
